-- 仅for Windows，用于大圣登陆相关的逻辑，所以只有PC国内才用的上，PC海外不会用这个
local E = require 'ejoysdk_lua.ejoysdk'
local Vendor = require "ejoysdk_lua.vendors.vendor"
local EM = require "ejoysdk_lua.ejoysdk_module"
--local UNI = require "ejoysdk_lua.vendors.unisdk"


local VENDOR_NAME = 'DS_PC'
local VENDOR_NAME_ALIGMES = 'ALIGAMES'
local M = Vendor:Inherit(VENDOR_NAME)

local logout_listener = nil
local ds_login_function = nil
local auth_listener = nil
local TAG = EM.MODULE.VENDORS.DS_PC


function M.set_ds_login_function(cb)
    if tostring(type(cb))  ~= 'function' then
        E.LOG.debug(TAG, 'set_ds_login_function, cb的类型不对')
        return
    end

    ds_login_function = cb
end

function M.set_auth_listener(cb)
    if tostring(type(cb)) ~= 'function' then
        E.LOG.debug(TAG, 'set_auth_listener, cb的类型不对')
        return
    end

    auth_listener = cb
end


-- 仅Windows的sdkconfig.json才有这个字段，国内/海外都要有，相当于包体渠道号
local function channel_id()
    local meta = E.CONFIG.get_config('unisdk_meta')
    if not meta or not meta.channel_id then
        E.LOG.warn(TAG, 'sdkconfig.json not has channel_id')
        return ''
    end

    return tostring(meta.channel_id)
end

--对于国内PC/移动端来说，只有998233是官方渠道，其他都非官渠，海外官渠则是998236,该文件是PC国内专用（大圣）
function M.is_official_channel_id()
    return channel_id() == '998233'
end


function M.init(opt, cb)
    -- 对接初始化时传入的logout_listener，才能把gangplank的logout通知发出去
    logout_listener = function( ... )
        local fun = opt.logout_listener
        if fun then
            fun()
        end
    end
    -- callback init success
    if cb then
        cb(true)
    end
end

function M.login()
    -- 后续如果PC增加外部渠道，就来这里扩展
    local AIRLINE_V2 = require "ejoysdk_lua.vendors.airline_v2"
    AIRLINE_V2.exec_login(function(succ, token, brand, accountOs)
        if succ then
            if ds_login_function then
                -- 走大圣登录的协议
                local account_params = {
                    channelId = channel_id(), -- 渠道号
                    ex = {
                        token = token or '',
                        airline = brand,
                        accountOs = accountOs
                    }
                }


                ds_login_function(account_params, function(ds_succ, body)

                    E.LOG.debug(TAG, body)
                    if ds_succ then
                        local outsource = {
                            platform = channel_id(),
                            with = VENDOR_NAME_ALIGMES,
                            ptoken = body.token,
                            pid = '', --info.pid,--这个值没有
                            guest = false,
                            ext = {}
                        }


                        if auth_listener then
                            E.LOG.debug(TAG, ' star call auth_listener_callback_function')
                            auth_listener(ds_succ, outsource, {})
                        else
                            E.LOG.debug(TAG, ' not has auth_listener_callback_function')
                        end

                    else

                        if auth_listener then
                            E.LOG.debug(TAG, ' star call auth_listener_callback_function')
                            local outsource = {
                                code = body.code,
                                msg = body.message or ''
                            }
                            auth_listener(ds_succ, outsource, {})
                        else
                            E.LOG.debug(TAG, ' not has auth_listener_callback_function')
                        end

                    end
                end)
            else
                E.LOG.debug(TAG,'走原来的登录协议，出问题啦-------')
                -- 走原来的协议
            end

        else

            local outsource = {
                code = -1,
                msg = 'PC H5 login failed'
            }
            auth_listener(false, outsource, {})
        end

    end)

    --UNI.login(VENDOR_NAME, {}) -- windows暂不支持这种形式的分发
end

function M.merge_info(info, pinfo)
    return M.merge_helper(info, pinfo)
end

function M.simple_token()
    return false
end

function M.check_token(_outsource, _info)
    M.login()
end

function M.logout()
    local AIRLINE_V2 = require "ejoysdk_lua.vendors.airline_v2"
    AIRLINE_V2.logout()
    logout_listener({})
end

function M.login_fail(_status, _last_login_params, _login_listener)
    return false
end


function M.open_user_center()
    -- 会从aligames.lua直接跳转到airline_v2，万一调用过来了就转过去airline_v2
    local AIRLINE_V2 = require "ejoysdk_lua.vendors.airline_v2"
    AIRLINE_V2.show_user_center()
end

M:is_implemented({"ACCOUNT"})

return M
